import { expect, test } from '@playwright/test';

test('Log in with a wrong password shows an error', async ({ page }) => {
  await test.step('Open the login page', async () => {
    await page.goto('/');
  });

  await test.step('Type the email', async () => {
    await page.getByRole('textbox', { name: 'Email', exact: true }).fill('ada@example.com');
  });

  await test.step('Type a wrong password', async () => {
    await page.locator('#password').fill('not-the-password');
  });

  await test.step('Click Sign in', async () => {
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  });

  await test.step('An error is shown and the user stays on the login page', async () => {
    await expect(page.getByRole('alert', { name: 'Wrong email or password', exact: true }).or(page.getByRole('alert').filter({ hasText: /^Wrong email or password$/ }))).toBeVisible();
    await expect(page.getByRole('heading', { name: 'Sign in', exact: true })).toBeVisible();
  });
});
